resource "zpa_application_segment" "this" {
  name              = "Example"
  description       = "Example"
  enabled           = true
  health_reporting  = "ON_ACCESS"
  bypass_type       = "NEVER"
  is_cname_enabled  = true
  tcp_port_range = [
    {
    from = "8080"
    to = "8080"
    }
  ]
  udp_port_range = [
    {
    from = "8080"
    to = "8080"
    }
  ]
  domain_names = ["example.com"]
  tags = [
    {
      key = zpa_tag_key.this.id,
      value = zpa_tag_key.this.values["example_value"].id  # or something similar, assuming an output
    }
  ]
}

resource "zpa_segment_group" "this" {
   name = "Example"
   description = "Example"
   enabled = true
 }

# Create Policy Access Rule V2
resource "zpa_policy_access_rule_v2" "this" {
  name          = "Example"
  description   = "Example"
  action        = "ALLOW"

  conditions {
    operands {
      object_type = "ENTITY_TAG_GRP"
      values      = [zpa_tag_group.this.id]
    }
  }
}
